import{cellRenderIntent}from'./render-intent.js';
import{groundSplitEditor,groundSplitMarkup}from'./foreground-split-ui.js';
import{auditProjectLayers,resolveProjectLayers}from'./project-authority.js';
export function layerAuthorityReview(api,{after=null}={}){const original=api.project(),pending=auditProjectLayers(original),decisions={};if(!pending.length){api.toast('The JSON has no unresolved layer conflicts.');after?.();return;}let selected=0,previewJob=0;
 api.modal('Resolve JSON layer conflicts',`<p>Your project contains ${pending.length} conflicting layer settings. Choose which JSON instruction to use. Ground stays below the player; originals are retained in the saved decision history.</p><label>Map tile<select id="authorityCell">${pending.map((c,i)=>`<option value="${i}">${api.esc(c.map)} · ${c.x},${c.y}</option>`).join('')}</select></label><p id="authorityMessage"></p><div style="display:flex;gap:12px;flex-wrap:wrap"><div style="display:flex;flex-direction:column"><b>Saved masks</b><canvas id="authorityVisual" width="160" height="160" style="width:160px;image-rendering:pixelated"></canvas></div><div style="display:flex;flex-direction:column"><b>Walk behind / separated foreground</b><canvas id="authorityBehind" width="160" height="160" style="width:160px;image-rendering:pixelated"></canvas></div></div><p class="hint-line">The coloured figure represents the player. The second option puts separate object/detail artwork above it.</p><button id="authorityUseVisual" type="button">Use saved masks for this tile</button><button id="authorityUseBehind" type="button">Use Walk behind for this tile</button>${groundSplitMarkup}<p id="authorityRemaining"></p><button id="authorityAllVisual" type="button">Use saved masks for all remaining conflicts</button><button id="authorityAllBehind" type="button">Use Walk behind where separate artwork exists</button><p>Review or edit object masks if neither interpretation gives the intended result. Use Separate foreground pixels when the artwork is baked into the ground. Selection and original settings are saved in the history.</p>`,async()=>{if(api.project()!==original)throw Error('The active project changed. Reopen layer review.');const unresolved=pending.filter(c=>!decisions[c.id]);if(unresolved.length)throw Error('Choose an interpretation for all '+unresolved.length+' remaining tiles.');const next=resolveProjectLayers(original,decisions);if(auditProjectLayers(next).length)throw Error('Some layer conflicts still need review.');await api.open(next);api.toast('Layer decisions saved in a separate project copy.');after?.();},'Save resolved project copy');
 const $=api.$;function status(){const c=pending[selected],map=original.maps.find(m=>m.id===c.mapId);$('#authoritySeparateGround').disabled=!map.layers.ground[c.y*map.width+c.x]||(map.nativeAssemblies||[]).some(a=>a.overlay&&c.x>=a.x&&c.y>=a.y&&c.x<a.x+a.w&&c.y<a.y+a.h&&a.overlay.mask[(c.y-a.y)*a.w+c.x-a.x]);$('#authorityMessage').textContent=c.message;$('#authorityUseBehind').disabled=!c.canPromote;$('#authorityRemaining').textContent=pending.filter(c=>!decisions[c.id]).length+' unresolved · this tile: '+(decisions[c.id]?.choice||decisions[c.id]||'not chosen');}
 async function previews(split=null){const job=++previewJob,c=pending[selected];split??=decisions[c.id]?.choice==='split-ground'?decisions[c.id]:null;status();if(!api.render)return;for(const [choice,target]of [['visual','authorityVisual'],['walk-behind','authorityBehind']]){const canvas=$('#'+target);if(!canvas)return;canvas.dataset.ready='false';const ctx=canvas.getContext('2d');ctx.fillStyle='#ddd';ctx.fillRect(0,0,160,160);if(choice==='walk-behind'&&!c.canPromote&&!split){ctx.fillStyle='#222';ctx.font='12px sans-serif';ctx.fillText('Separate foreground',8,65);ctx.fillText('pixels to preview.',8,83);continue;}try{const p=resolveProjectLayers(original,{[c.id]:choice==='walk-behind'&&split?split:choice}),m=p.maps.find(m=>m.id===c.mapId),planes=await api.render(m,{extraAssets:split?[split.split.lowerAsset,split.split.upperAsset]:[]});if(job!==previewJob)return;const make=data=>{const out=document.createElement('canvas');out.width=data.width;out.height=data.height;out.getContext('2d').putImageData(data,0,0);return out;},lower=make(planes.lower),upper=make(planes.upper),middle=planes.middle&&make(planes.middle),sx=Math.max(0,c.x*16-32),sy=Math.max(0,c.y*16-32),draw=im=>ctx.drawImage(im,sx,sy,80,80,0,0,160,160);ctx.imageSmoothingEnabled=false;draw(lower);if(middle)draw(middle);const foreground=!!middle||cellRenderIntent(m,c.x,c.y)?.foreground;if(!foreground)draw(upper);ctx.fillStyle='#222';const px=(c.x*16+8-sx)*2,py=(c.y*16+8-sy)*2;ctx.fillRect(px-5,py-8,10,18);ctx.fillStyle='#ed68cc';ctx.fillRect(px-3,py-6,6,12);if(foreground)draw(upper);canvas.dataset.ready='true';lower.width=upper.width=0;if(middle)middle.width=0;}catch(e){if(job===previewJob){ctx.fillStyle='#222';ctx.font='12px sans-serif';ctx.fillText('Preview unavailable',4,20);}}}}
 const splitter=groundSplitEditor(api,original,{current:()=>pending[selected],onPreview:previews,onChoose:choice=>choose(choice)});$('#authoritySeparateGround').onclick=()=>splitter.open();const choose=choice=>{const c=pending[selected];if(choice==='walk-behind'&&!c.canPromote)return;decisions[c.id]=choice;splitter.reset();const next=pending.findIndex(c=>!decisions[c.id]);if(next>=0){selected=next;$('#authorityCell').value=String(next);}previews();};$('#authorityCell').onchange=()=>{selected=+$('#authorityCell').value;splitter.reset();previews();};$('#authorityUseVisual').onclick=()=>choose('visual');$('#authorityUseBehind').onclick=()=>choose('walk-behind');$('#authorityAllVisual').onclick=()=>{for(const c of pending)decisions[c.id]??='visual';status();};$('#authorityAllBehind').onclick=()=>{for(const c of pending)if(c.canPromote)decisions[c.id]??='walk-behind';status();};previews();}
